<?php $title="Teachers";require "../includes/header.php";$teachers=$pdo->query("SELECT t.*,d.name dept FROM teachers t LEFT JOIN departments d ON d.id=t.department_id ORDER BY t.id DESC")->fetchAll();$deps=$pdo->query("SELECT * FROM departments")->fetchAll();?><div class="d-flex justify-content-between mb-3"><h2>Teachers</h2><a href="add.php" class="btn btn-primary">+ Add Teacher</a></div><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Department</th><th>Designation</th><th>Actions</th></tr></thead><tbody><?php foreach($teachers as $t):?><tr><td><?=$t['teacher_id']?></td><td><?=htmlspecialchars($t['name'])?></td><td><?=$t['email']?></td><td><?=$t['phone']?></td><td><?=htmlspecialchars($t['dept']??'-')?></td><td><?=$t['designation']?></td><td><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?=$t['id']?>">Edit</a> <a data-confirm="Delete teacher?" class="btn btn-sm btn-outline-danger" href="delete.php?id=<?=$t['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div><?php require "../includes/footer.php";?>